// This file is not generated by Stainless and is preserved across codegen runs.
// It holds unit tests for the hand-written InferenceSecretService.DeleteAndPoll.
//
// The tests are self-contained: each drives a local httptest.Server, so they run
// under a plain `go test` (or `scripts/test`) without needing the Prism/Steady
// mock server.

package cloud_test

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/G-Core/gcore-go"
	"github.com/G-Core/gcore-go/cloud"
	"github.com/G-Core/gcore-go/option"
)

const inferenceSecretAndPollName = "my-aws-iam-secret"

// newInferenceSecretDeleteServer answers the DELETE with deleteStatus and each
// GET with the next status from getStatuses, repeating the last one. It records
// the path of every GET so tests can check which secret was polled.
func newInferenceSecretDeleteServer(deleteStatus int, getStatuses []int, gets *atomic.Int32, getPath *atomic.Value) *httptest.Server {
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == http.MethodDelete {
			w.WriteHeader(deleteStatus)
			return
		}
		getPath.Store(r.URL.Path)
		n := int(gets.Add(1)) - 1
		status := getStatuses[min(n, len(getStatuses)-1)]
		w.WriteHeader(status)
		if status == http.StatusOK {
			_ = json.NewEncoder(w).Encode(map[string]any{
				"name": inferenceSecretAndPollName,
				"type": "aws-iam",
				"data": map[string]any{"aws_access_key_id": "AKIA", "aws_secret_access_key": "secret"},
			})
			return
		}
		_, _ = io.WriteString(w, `{"message":"status `+http.StatusText(status)+`"}`)
	}))
}

func inferenceSecretDelete(server *httptest.Server, timeoutSeconds int64, opts ...option.RequestOption) error {
	return inferenceSecretDeleteWithClient(server, nil, timeoutSeconds, opts...)
}

// inferenceSecretDeleteWithClient also applies clientOpts when building the
// client, so they reach every request the service makes.
func inferenceSecretDeleteWithClient(server *httptest.Server, clientOpts []option.RequestOption, timeoutSeconds int64, opts ...option.RequestOption) error {
	client := gcore.NewClient(append([]option.RequestOption{
		option.WithBaseURL(server.URL),
		option.WithAPIKey("test"),
		option.WithCloudProjectID(1),
	}, clientOpts...)...)
	return client.Cloud.Inference.Secrets.DeleteAndPoll(
		context.Background(), inferenceSecretAndPollName, cloud.InferenceSecretDeleteParams{},
		append([]option.RequestOption{
			option.WithMaxRetries(0),
			option.WithPollingIntervalSeconds(1),
			option.WithPollingTimeoutSeconds(timeoutSeconds),
		}, opts...)...,
	)
}

// The DELETE answers before the secret is gone, so DeleteAndPoll waits for the
// GET to return 404, keeps polling through transient GET errors, and reports the
// last of them only when the polling timeout runs out.
func TestInferenceSecretDeleteAndPoll(t *testing.T) {
	t.Run("waits until the secret is gone", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusNoContent, []int{http.StatusOK, http.StatusNotFound}, &gets, &getPath)
		defer server.Close()

		if err := inferenceSecretDelete(server, 30); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := gets.Load(); got != 2 {
			t.Errorf("served %d GETs, want 2", got)
		}
		if want := "/cloud/v3/inference/1/secrets/" + inferenceSecretAndPollName; getPath.Load() != want {
			t.Errorf("polled %v, want %s (default project from the client)", getPath.Load(), want)
		}
	})

	t.Run("keeps polling through a transient GET error", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusNoContent,
			[]int{http.StatusInternalServerError, http.StatusOK, http.StatusNotFound}, &gets, &getPath)
		defer server.Close()

		if err := inferenceSecretDelete(server, 30); err != nil {
			t.Fatalf("a transient GET error after a successful DELETE should not fail: %v", err)
		}
		if got := gets.Load(); got != 3 {
			t.Errorf("served %d GETs, want 3", got)
		}
	})

	// The CLI passes WithResponseBodyInto to capture the DELETE response. It must
	// not reach the GETs, or the request layer would skip decoding them.
	t.Run("a caller response target does not hide the 404", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusNoContent, []int{http.StatusOK, http.StatusNotFound}, &gets, &getPath)
		defer server.Close()

		var res []byte
		if err := inferenceSecretDelete(server, 30, option.WithResponseBodyInto(&res)); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := gets.Load(); got != 2 {
			t.Errorf("served %d GETs, want 2", got)
		}
	})

	// A response target set on the client is inherited by every request the
	// service makes, so the GETs have to drop it as well.
	t.Run("a response target on the client is not overwritten by the GETs", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusNoContent, []int{http.StatusOK, http.StatusNotFound}, &gets, &getPath)
		defer server.Close()

		var res []byte
		if err := inferenceSecretDeleteWithClient(server, []option.RequestOption{option.WithResponseBodyInto(&res)}, 30); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := gets.Load(); got != 2 {
			t.Errorf("served %d GETs, want 2", got)
		}
		if strings.Contains(string(res), inferenceSecretAndPollName) {
			t.Errorf("the client's response target holds a GET body: %s", res)
		}
	})

	t.Run("timeout reports the secret and the last error", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusNoContent, []int{http.StatusBadGateway}, &gets, &getPath)
		defer server.Close()

		err := inferenceSecretDelete(server, 2)
		if err == nil {
			t.Fatal("expected an error once the polling timeout runs out")
		}
		for _, want := range []string{inferenceSecretAndPollName, "still reported after delete", "502"} {
			if !strings.Contains(err.Error(), want) {
				t.Errorf("error %q does not mention %q", err, want)
			}
		}
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Errorf("error %q does not wrap context.DeadlineExceeded", err)
		}
	})

	t.Run("delete error is returned without polling", func(t *testing.T) {
		var gets atomic.Int32
		var getPath atomic.Value
		server := newInferenceSecretDeleteServer(http.StatusConflict, []int{http.StatusOK}, &gets, &getPath)
		defer server.Close()

		if err := inferenceSecretDelete(server, 30); err == nil {
			t.Fatal("expected the DELETE error")
		}
		if got := gets.Load(); got != 0 {
			t.Errorf("served %d GETs after a failed DELETE, want 0", got)
		}
	})
}
